const oauth: unknown = JSON.parse(stripBom(readFileSync(oauthPath, "utf-8")));
if (typeof oauth !== "object" || oauth === null || Array.isArray(oauth)) {
	throw new Error("Invalid oauth.json: expected an object");
}
// Validate before renaming so that malformed input is never destroyed.
const credentials: Array<[string, object]> = [];
for (const [provider, cred] of Object.entries(oauth)) {
	if (typeof cred !== "object" || cred === null || Array.isArray(cred)) {
		throw new Error(`Invalid oauth.json credential for provider "${provider}"`);
	}
	credentials.push([provider, cred]);
}
for (const [provider, cred] of credentials) {
	migrated[provider] = { type: "oauth", ...cred };
	providers.push(provider);
}
